<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getComboboxContext } from './combobox-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet<[unknown[]]>; placeholder?: string; ref?: HTMLSpanElement | null; } let { children, placeholder = '', ref = $bindable(null), ...rest }: Props = $props(); const box = getComboboxContext();</script><span bind:this={ref} {...rest} data-placeholder={box.selectedValues.length === 0 ? '' : undefined}>{#if children}{@render children(box.selectedValues)}{:else}{box.selectedValues.length ? box.selectedValues.map((item) => box.labelFor(item)).join(', ') : placeholder}{/if}</span>
